-- ════════════════════════════════════════════════════════════════
-- agicare — estrutura MySQL 8 (convertida do Supabase/Postgres)
--
-- Gerado a partir do estado FINAL das 122 migrations de
-- supabase/migrations/, aplicadas num Postgres real e depois traduzidas.
--
-- Requer MySQL 8.0.16+ (usa DEFAULT de expressão, CHECK e JSON).
-- Charset utf8mb4 (acentuação e emoji), engine InnoDB (FK + transações).
--
-- ┌─ O QUE MUDA EM RELAÇÃO AO POSTGRES ─────────────────────────────┐
-- │ · uuid            → CHAR(36) com DEFAULT (UUID())               │
-- │ · timestamptz     → DATETIME(6) (MySQL não guarda o timezone;   │
-- │                     grave sempre em UTC na aplicação)           │
-- │ · boolean         → TINYINT(1) (1 = true, 0 = false)            │
-- │ · jsonb / text[]  → JSON                                        │
-- │ · enums Postgres  → ENUM nativo do MySQL                        │
-- │ · RLS             → NÃO EXISTE em MySQL. Toda a autorização que │
-- │                     hoje é feita por Row Level Security precisa │
-- │                     ser garantida na aplicação. Ver o bloco no  │
-- │                     fim deste arquivo.                          │
-- │ · auth.users      → tabela auth_users (substitui o Supabase Auth)│
-- └─────────────────────────────────────────────────────────────────┘
-- ════════════════════════════════════════════════════════════════
--
-- ⚠  ESTE SCRIPT ESPERA UM BANCO `agicare` LIMPO.
--    Ele cria as tabelas do zero e insere os dados semeados, então NÃO é
--    idempotente: rodar duas vezes falha (índice ou chave duplicada). Se uma
--    importação anterior falhou no meio, apague o banco antes de repetir:
--
--      mysql -u root -e "DROP DATABASE IF EXISTS agicare;"
--
--    Os CREATE TABLE são intencionalmente SEM "IF NOT EXISTS": assim, um
--    banco sujo falha na primeira linha com mensagem clara, em vez de
--    quebrar 1.400 linhas depois com um erro confuso.
-- ════════════════════════════════════════════════════════════════

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET @@session.sql_mode = 'STRICT_ALL_TABLES';

CREATE DATABASE IF NOT EXISTS `agicare`
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `agicare`;

-- ────────────────────────────────────────────────────────────────
-- auth_users — substitui a tabela auth.users do Supabase Auth.
-- O Supabase cuidava de login/senha/JWT fora do schema public; em
-- MySQL isso passa a ser responsabilidade da aplicação. A senha deve
-- ser gravada como HASH (bcrypt/argon2), NUNCA em texto puro.
-- ────────────────────────────────────────────────────────────────
CREATE TABLE `auth_users` (
  `id`                 CHAR(36)     NOT NULL DEFAULT (UUID()),
  `email`              VARCHAR(255) NOT NULL,
  `encrypted_password` VARCHAR(255) NULL,
  `email_confirmed_at` DATETIME(6)  NULL,
  `last_sign_in_at`    DATETIME(6)  NULL,
  `raw_user_meta_data` JSON         NULL,
  `created_at`         DATETIME(6)  NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at`         DATETIME(6)  NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
                                      ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `auth_users_email_key` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ── access_logs ──
CREATE TABLE `access_logs` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `user_id` CHAR(36) NULL,
  `user_name` TEXT NULL,
  `user_role` ENUM('admin','medico','recepcao','paciente') NULL,
  `patient_id` CHAR(36) NULL,
  `patient_name` TEXT NULL,
  `module` TEXT NOT NULL,
  `action` VARCHAR(255) NOT NULL DEFAULT 'view',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `clinic_id` CHAR(36) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── anamnese_templates ──
CREATE TABLE `anamnese_templates` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `clinic_id` CHAR(36) NOT NULL,
  `specialty` VARCHAR(255) NOT NULL,
  `fields` JSON NOT NULL DEFAULT (JSON_ARRAY()),
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_anamnese_templates_clinic_specialty` (`clinic_id`, `specialty`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── anamneses ──
CREATE TABLE `anamneses` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `patient_id` CHAR(36) NOT NULL,
  `professional_id` CHAR(36) NULL,
  `specialty` TEXT NOT NULL,
  `fields` JSON NOT NULL DEFAULT (JSON_OBJECT()),
  `consent_given` TINYINT(1) NOT NULL DEFAULT 0,
  `signature` TEXT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `clinic_id` CHAR(36) NOT NULL,
  `queue_entry_id` CHAR(36) NULL,
  `created_by` CHAR(36) NULL,
  `cancelled_at` DATETIME(6) NULL,
  `cancelled_by` CHAR(36) NULL,
  `cancel_reason` TEXT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── appointment_notifications ──
CREATE TABLE `appointment_notifications` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `channel` ENUM('sms','email','whatsapp') NOT NULL,
  `protocol` VARCHAR(255) NOT NULL,
  `patient_id` CHAR(36) NULL,
  `recipient` TEXT NULL,
  `sent_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `clinic_id` CHAR(36) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── appointments ──
CREATE TABLE `appointments` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `patient_id` CHAR(36) NOT NULL,
  `professional_id` CHAR(36) NULL,
  `starts_at` DATETIME(6) NOT NULL,
  `ends_at` DATETIME(6) NOT NULL,
  `status` ENUM('agendado','confirmado','em_atendimento','concluido','cancelado','faltou','aguardando_recepcao','em_atendimento_recepcao','aguardando_profissional','em_atendimento_profissional','checkout') NOT NULL DEFAULT 'agendado',
  `reason` TEXT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by` CHAR(36) NULL,
  `schedule_id` CHAR(36) NULL,
  `clinic_id` CHAR(36) NOT NULL,
  `check_in` DATETIME(6) NULL,
  `specialty` TEXT NULL,
  `service_type` TEXT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── assessment_scales ──
CREATE TABLE `assessment_scales` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `patient_id` CHAR(36) NULL,
  `professional_id` CHAR(36) NULL,
  `professional_name` TEXT NULL,
  `scale` ENUM('glasgow','fugulin','braden') NOT NULL,
  `score` INT NOT NULL DEFAULT 0,
  `classification` TEXT NULL,
  `details` JSON NOT NULL DEFAULT (JSON_OBJECT()),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `clinic_id` CHAR(36) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── attendance_options ──
CREATE TABLE `attendance_options` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `clinic_id` CHAR(36) NOT NULL,
  `category` VARCHAR(255) NOT NULL,
  `label` TEXT NOT NULL,
  `value` VARCHAR(255) NOT NULL,
  `sort_order` INT NOT NULL DEFAULT 0,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `parent_id` CHAR(36) NULL,
  `description` TEXT NULL,
  `sterilization_method` TEXT NULL,
  `validity_date` DATE NULL,
  `lot_code` TEXT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── attendance_records ──
CREATE TABLE `attendance_records` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `clinic_id` CHAR(36) NOT NULL,
  `queue_entry_id` CHAR(36) NULL,
  `patient_id` CHAR(36) NULL,
  `professional_id` CHAR(36) NULL,
  `patient_name` TEXT NULL,
  `medico` TEXT NULL,
  `especialidade` TEXT NULL,
  `encaminhamento` TEXT NULL,
  `carater` TEXT NULL,
  `procedencia` TEXT NULL,
  `centro_custo` TEXT NULL,
  `origem` TEXT NULL,
  `data_entrada` DATE NULL,
  `privado_liberdade` TINYINT(1) NOT NULL DEFAULT 0,
  `gestante` TINYINT(1) NOT NULL DEFAULT 0,
  `convenio` TEXT NULL,
  `plano` TEXT NULL,
  `carteira` TEXT NULL,
  `validade` DATE NULL,
  `validador` TEXT NULL,
  `resp_o_mesmo` TINYINT(1) NOT NULL DEFAULT 0,
  `resp_nome` TEXT NULL,
  `resp_documento` TEXT NULL,
  `resp_parentesco` TEXT NULL,
  `observacoes` TEXT NULL,
  `created_by` CHAR(36) NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `attendance_records_carater_check` CHECK ((carater IN ('urgencia', 'eletivo'))),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── billable_events ──
CREATE TABLE `billable_events` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `code` VARCHAR(255) NOT NULL,
  `patient_id` CHAR(36) NULL,
  `professional_id` CHAR(36) NULL,
  `appointment_id` CHAR(36) NULL,
  `kind` ENUM('convenio','particular','empresa') NOT NULL DEFAULT 'particular',
  `service` TEXT NULL,
  `amount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `status` ENUM('pendente','faturado','glosado') NOT NULL DEFAULT 'pendente',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `clinic_id` CHAR(36) NOT NULL,
  `discount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `surcharge` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `net_amount` DECIMAL(12,2) NULL,
  `payment_method` TEXT NULL,
  `checked_out_at` DATETIME(6) NULL,
  `nf_number` TEXT NULL,
  `nf_issue_date` DATE NULL,
  `nf_due_date` DATE NULL,
  `nf_terms` TEXT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `billable_events_code_key` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── billing_items ──
CREATE TABLE `billing_items` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `event_id` CHAR(36) NULL,
  `kind` ENUM('tuss','material','ajuste') NOT NULL DEFAULT 'tuss',
  `code` TEXT NULL,
  `description` TEXT NOT NULL,
  `quantity` DECIMAL(12,2) NOT NULL DEFAULT 1,
  `unit_price` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `amount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `clinic_id` CHAR(36) NOT NULL,
  `source` TEXT NULL,
  `procedure_id` CHAR(36) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── budget_items ──
CREATE TABLE `budget_items` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `clinic_id` CHAR(36) NOT NULL,
  `budget_id` CHAR(36) NOT NULL,
  `description` TEXT NOT NULL,
  `quantity` DECIMAL(12,2) NOT NULL DEFAULT 1,
  `unit_price` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `amount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── budgets ──
CREATE TABLE `budgets` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `clinic_id` CHAR(36) NOT NULL,
  `code` TEXT NULL,
  `patient_id` CHAR(36) NULL,
  `professional_id` CHAR(36) NULL,
  `description` TEXT NULL,
  `amount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `status` ENUM('proposto','aprovado','recusado') NOT NULL DEFAULT 'proposto',
  `decided_at` DATETIME(6) NULL,
  `created_by` CHAR(36) NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── care_checks ──
CREATE TABLE `care_checks` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `sae_id` CHAR(36) NULL,
  `patient_id` CHAR(36) NULL,
  `description` TEXT NOT NULL,
  `scheduled_at` DATETIME(6) NOT NULL,
  `status` ENUM('pendente','administrado','aprazado') NOT NULL DEFAULT 'pendente',
  `justification` TEXT NULL,
  `professional_id` CHAR(36) NULL,
  `professional_name` TEXT NULL,
  `checked_at` DATETIME(6) NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `clinic_id` CHAR(36) NOT NULL,
  `created_by` CHAR(36) NULL,
  `queue_entry_id` CHAR(36) NULL,
  `cancelled_at` DATETIME(6) NULL,
  `cancelled_by` CHAR(36) NULL,
  `cancel_reason` TEXT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── care_orders ──
CREATE TABLE `care_orders` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `prescription_id` CHAR(36) NULL,
  `patient_id` CHAR(36) NOT NULL,
  `name` TEXT NOT NULL,
  `frequency` TEXT NULL,
  `duration` TEXT NULL,
  `observations` TEXT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `clinic_id` CHAR(36) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── cargos ──
CREATE TABLE `cargos` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `clinic_id` CHAR(36) NOT NULL,
  `name` TEXT NOT NULL,
  `base_role` ENUM('admin','medico','recepcao','paciente') NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `chk_cargos_base_role` CHECK ((base_role IN ('admin', 'medico', 'recepcao'))),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── certificates ──
CREATE TABLE `certificates` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `patient_id` CHAR(36) NOT NULL,
  `professional_id` CHAR(36) NULL,
  `kind` TEXT NOT NULL,
  `days` INT NULL,
  `start_date` DATE NULL,
  `end_date` DATE NULL,
  `diagnosis` TEXT NULL,
  `cid10` TEXT NULL,
  `reason` TEXT NULL,
  `post_discharge` TEXT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `clinic_id` CHAR(36) NOT NULL,
  `issue_date` DATE NULL,
  `observation` TEXT NULL,
  `show_cid` TINYINT(1) NOT NULL DEFAULT 1,
  `discharge_at` DATETIME(6) NULL,
  `discharge_detail` TEXT NULL,
  `prescription_text` TEXT NULL,
  `queue_entry_id` CHAR(36) NULL,
  `created_by` CHAR(36) NULL,
  `cancelled_at` DATETIME(6) NULL,
  `cancelled_by` CHAR(36) NULL,
  `cancel_reason` TEXT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── cid_codes ──
CREATE TABLE `cid_codes` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `code` VARCHAR(255) NOT NULL,
  `description` TEXT NOT NULL,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `cid_codes_code_key` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── clinic_members ──
CREATE TABLE `clinic_members` (
  `clinic_id` CHAR(36) NOT NULL,
  `user_id` CHAR(36) NOT NULL,
  `role` ENUM('admin','medico','recepcao','paciente') NOT NULL DEFAULT 'recepcao',
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `cargo_id` CHAR(36) NULL,
  PRIMARY KEY (`clinic_id`, `user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── clinic_settings ──
CREATE TABLE `clinic_settings` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `clinic_name` TEXT NULL,
  `cnpj` TEXT NULL,
  `phone` TEXT NULL,
  `email` TEXT NULL,
  `address` TEXT NULL,
  `cep` TEXT NULL,
  `business_hours` TEXT NULL,
  `language` VARCHAR(255) NOT NULL DEFAULT 'pt-BR',
  `timezone` VARCHAR(255) NOT NULL DEFAULT 'gmt-3',
  `date_format` VARCHAR(255) NOT NULL DEFAULT 'dmy',
  `time_format` VARCHAR(255) NOT NULL DEFAULT '24h',
  `currency` VARCHAR(255) NOT NULL DEFAULT 'brl',
  `notify_email` TINYINT(1) NOT NULL DEFAULT 1,
  `notify_sms` TINYINT(1) NOT NULL DEFAULT 0,
  `notify_push` TINYINT(1) NOT NULL DEFAULT 1,
  `two_factor` TINYINT(1) NOT NULL DEFAULT 0,
  `password_policy` VARCHAR(255) NOT NULL DEFAULT 'media',
  `backup_frequency` VARCHAR(255) NOT NULL DEFAULT 'diario',
  `backup_retention_days` INT NOT NULL DEFAULT 30,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `clinic_id` CHAR(36) NOT NULL,
  `security` JSON NOT NULL DEFAULT (JSON_OBJECT()),
  `backup` JSON NOT NULL DEFAULT (JSON_OBJECT()),
  `notifications` JSON NOT NULL DEFAULT (JSON_OBJECT()),
  `branding` JSON NOT NULL DEFAULT (JSON_OBJECT()),
  `attendance_flow` JSON NOT NULL DEFAULT (JSON_OBJECT('stages', JSON_ARRAY('recepcao', 'triagem', 'atendimento'))),
  `totem_enabled` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── clinics ──
CREATE TABLE `clinics` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `name` TEXT NOT NULL,
  `slug` VARCHAR(255) NULL,
  `cnpj` VARCHAR(255) NULL,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `clinics_cnpj_key` (`cnpj`),
  UNIQUE KEY `clinics_slug_key` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── consent_templates ──
CREATE TABLE `consent_templates` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `clinic_id` CHAR(36) NOT NULL,
  `title` TEXT NOT NULL,
  `body` TEXT NOT NULL,
  `sort_order` INT NOT NULL DEFAULT 0,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── consents ──
CREATE TABLE `consents` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `patient_id` CHAR(36) NOT NULL,
  `professional_id` CHAR(36) NULL,
  `context` TEXT NOT NULL,
  `accepted` TINYINT(1) NOT NULL DEFAULT 0,
  `signature` TEXT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by` CHAR(36) NULL,
  `clinic_id` CHAR(36) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── dental_chart_marks ──
CREATE TABLE `dental_chart_marks` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `chart_id` CHAR(36) NOT NULL,
  `tooth` SMALLINT NOT NULL,
  `marking` VARCHAR(255) NOT NULL,
  `note` TEXT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `dental_chart_marks_marking_check` CHECK ((marking IN ('ausente', 'extracao_indicada', 'restauracao', 'carie', 'tratamento_canal', 'coroa', 'protese_fixa', 'implante', 'protese_removivel', 'selante', 'outros'))),
  CONSTRAINT `dental_chart_marks_tooth_fdi_check` CHECK ((tooth IN (11, 12, 13, 14, 15, 16, 17, 18, 21, 22, 23, 24, 25, 26, 27, 28, 31, 32, 33, 34, 35, 36, 37, 38, 41, 42, 43, 44, 45, 46, 47, 48))),
  PRIMARY KEY (`id`),
  UNIQUE KEY `dental_chart_marks_chart_tooth_marking_key` (`chart_id`, `tooth`, `marking`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ── dental_charts ──
CREATE TABLE `dental_charts` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `clinic_id` CHAR(36) NOT NULL,
  `patient_id` CHAR(36) NOT NULL,
  `professional_id` CHAR(36) NULL,
  `queue_entry_id` CHAR(36) NULL,
  `notes` TEXT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `created_by` CHAR(36) NULL,
  `cancelled_at` DATETIME(6) NULL,
  `cancelled_by` CHAR(36) NULL,
  `cancel_reason` TEXT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

