  `product_id` CHAR(36) NULL,
  `name` TEXT NOT NULL,
  `quantity` TEXT NULL,
  `location` TEXT NULL,
  `barcode` TEXT NULL,
  `lot` TEXT NULL,
  `expiry` DATE NULL,
  `picked` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
