-- ── dispensations ──
CREATE TABLE `dispensations` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `code` TEXT NOT NULL,
  `kind` ENUM('prescricao','setor') NOT NULL DEFAULT 'prescricao',
  `status` ENUM('pendente','separacao','concluido','cancelado') NOT NULL DEFAULT 'pendente',
  `urgent` TINYINT(1) NOT NULL DEFAULT 0,
  `patient_id` CHAR(36) NULL,
  `professional_id` CHAR(36) NULL,
  `origin_label` TEXT NULL,
  `origin_name` TEXT NULL,
  `origin_ref` TEXT NULL,
