-- ── payments ──
CREATE TABLE `payments` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `clinic_id` CHAR(36) NOT NULL,
  `event_id` CHAR(36) NULL,
  `method` TEXT NOT NULL,
  `status` VARCHAR(255) NOT NULL DEFAULT 'pendente',
