CREATE TABLE `product_min_max` (
  `id` CHAR(36) NOT NULL DEFAULT (UUID()),
  `clinic_id` CHAR(36) NOT NULL,
  `product_id` CHAR(36) NOT NULL,
  `min_quantity` DECIMAL(12,2) NULL,
  `max_quantity` DECIMAL(12,2) NULL,
