  `weight` DECIMAL(5,2) NULL,
  `height` DECIMAL(4,2) NULL,
  `spo2` INT NULL,
  `glucose` INT NULL,
  `notes` TEXT NULL,
  `recorded_by` CHAR(36) NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
